// Кросс-платформенные локаторы для React Native (Expo) приложения.
// accessibilityLabel из кода приложения = aria-label в web-сборке = content-desc (Android) / name (iOS).
import { $, $$, driver, expect } from '@wdio/globals';

export const isAndroid = () => driver.isAndroid;
const q = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
/** Регэксп для UiSelector на Android: парсер Appium НЕ снимает «\\», поэтому «\d» передаём как есть (удвоенный искал буквальный «\d» — регресс 15.11). */
export const qRe = (re: string) => re.replace(/"/g, '\\"');

/** iOS: доступный контейнер React Native (карточка, кнопка) склеивает тексты детей через «, »
 *  («מנחה, נוסח התפילה אשכנזי»), и сами тексты внутри не видны. Ищем точный текст или целую часть такой подписи. */
const iosExact = (t: string) => {
  const s = q(t);
  return `label == "${s}" OR value == "${s}" OR name == "${s}" OR label BEGINSWITH "${s}, " OR label BEGINSWITH "${s} — " OR label ENDSWITH ", ${s}" OR label CONTAINS ", ${s}, "`;
};
/** Элемент по точному тексту (или подписи доступности). */
export function byText(text: string) {
  return isAndroid()
    ? $(`android=new UiSelector().text("${q(text)}")`)
    : $(`-ios predicate string:${iosExact(text)}`);
}
/** Все элементы по точному тексту. */
export function allByText(text: string) {
  return isAndroid()
    ? $$(`android=new UiSelector().text("${q(text)}")`)
    : $$(`-ios predicate string:${iosExact(text)}`);
}
/** Элемент, текст которого содержит подстроку. */
export function byTextContains(part: string) {
  return isAndroid()
    ? $(`android=new UiSelector().textContains("${q(part)}")`)
    : $(`-ios predicate string:label CONTAINS "${q(part)}" OR value CONTAINS "${q(part)}"`);
}
/** Элемент по регулярному выражению (синтаксис Java/ICU; без флагов). */
export function byTextMatches(re: string) {
  return isAndroid()
    ? $(`android=new UiSelector().textMatches("${qRe(re)}")`)
    : $(`-ios predicate string:label MATCHES "${q(re)}" OR value MATCHES "${q(re)}"`);
}
/** Элемент по accessibilityLabel (aria-label в web-тестах: getByLabel / getByRole name). */
export function byLabel(label: string) {
  return $(`~${label}`);
}
/** Подпись доступности начинается с префикса (например «בחירת נוסח»). */
export function byLabelStartsWith(prefix: string) {
  return isAndroid()
    ? $(`android=new UiSelector().descriptionStartsWith("${q(prefix)}")`)
    : $(`-ios predicate string:name BEGINSWITH "${q(prefix)}" OR label BEGINSWITH "${q(prefix)}"`);
}

export async function tapText(text: string) {
  const el = await byText(text);
  await el.waitForDisplayed();
  await el.click();
}
export async function tapLabel(label: string) {
  const el = await byLabel(label);
  await el.waitForDisplayed();
  await el.click();
}

export async function expectVisibleText(text: string) {
  await expect(byText(text)).toBeDisplayed();
}
export async function expectTextContains(part: string) {
  await expect(byTextContains(part)).toBeDisplayed();
}
export async function expectNoText(text: string) {
  await expect(byText(text)).not.toBeDisplayed();
}

/** Прокрутить вниз до элемента с текстом (до N свайпов). */
export async function scrollToText(text: string, max = 8) {
  if (isAndroid()) {
    const el = await $(`android=new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().textContains("${q(text)}"))`);
    if (await el.isExisting()) return el;
  }
  for (let i = 0; i < max; i++) {
    const el = await byTextContains(text);
    if (await el.isDisplayed().catch(() => false)) return el;
    await swipeUp();
  }
  throw new Error(`Не найден текст после прокрутки: ${text}`);
}

export async function swipeUp() {
  const { width, height } = await driver.getWindowSize();
  await driver.action('pointer', { parameters: { pointerType: 'touch' } })
    .move({ x: Math.round(width / 2), y: Math.round(height * 0.75) })
    .down().pause(80)
    .move({ duration: 400, x: Math.round(width / 2), y: Math.round(height * 0.3) })
    .up().perform();
}

/** Счётчик страниц «N מתוך M» на экране молитвы. */
export async function pageCounter(): Promise<string> {
  const el = await byTextMatches('\\d+ מתוך \\d+');
  await el.waitForDisplayed();
  const t = (await el.getText()) || (await el.getAttribute(isAndroid() ? 'content-desc' : 'label')) || '';
  return (t.match(/\d+ מתוך \d+/) ?? [''])[0];
}
